actions.command:
/bin/zsh -lc "node --input-type=module <<'JS'
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { resolve } from 'node:path';
const cli = resolve('tools/install-release.mjs');
const destination = resolve('owned-package');
const inspect = spawnSync(process.execPath, [cli, 'inspect', '--target', 'codex', '--destination', destination], { encoding: 'utf8' });
assert.equal(inspect.status, 0, inspect.stderr);
assert.deepEqual(JSON.parse(inspect.stdout), { target: 'codex', destination, installedVersion: '0.5.0', installedFileCount: 1 });
for (const entry of [resolve('installer.mjs'), resolve('source/tools/install-release.mjs'), cli]) {
  const invalid = spawnSync(process.execPath, [entry, 'unknown-action'], { encoding: 'utf8' });
  assert.equal(invalid.status, 1);
  assert.match(invalid.stderr, /action must be/);
}
for (const argv of [null, '/missing/entry.mjs', resolve('history.json')]) {
  const code = "'`${argv === null ? '"'delete process.argv[1]' : "'`process.argv[1] = ${JSON.stringify(argv)}`}; await import(${JSON.stringify(cli)});`;
  const imported = spawnSync(process.execPath, ['"'--input-type=module', '-e', code], { encoding: 'utf8' });
  assert.equal(imported.status, 0, imported.stderr);
  assert.equal(imported.stdout, '');
  assert.equal(imported.stderr, '');
}
console.log('Direct inspect output preserved; malformed actions exit 1 on all three paths; imports remain silent with absent, missing, or unrelated entry paths.');
JS"
